from ext import *
ext('c10_eng_ch4',[
C("🎞️","सत्यजित राय का परिचय",["कोलकाता के महान फ़िल्मकार","पथेर पांचाली, 1955","कान फ़िल्म समारोह में सम्मान","ऑस्कर का मानद पुरस्कार"],"निबंध के लेखक सत्यजित राय कोलकाता के थे और भारत के सबसे महान फ़िल्मकारों में गिने जाते हैं। उनकी पहली फ़िल्म पथेर पांचाली उन्नीस सौ पचपन में आई, जो बंगाल के एक गाँव के ग़रीब परिवार की सच्ची कहानी है। इस फ़िल्म को देश और दुनिया में बहुत सराहना मिली और उन्हें कई अंतरराष्ट्रीय सम्मान मिले। जीवन के अंत में उन्हें भारत रत्न भी दिया गया और ऑस्कर का मानद पुरस्कार भी मिला। वे फ़िल्म बनाने के साथ-साथ लेखक, चित्रकार और संगीतकार भी थे, इसलिए सिनेमा पर उनकी राय बहुत मायने रखती है।"),
C("🌍","सिनेमा की शुरुआत",["सिनेमा पश्चिम से आया","भारत में पहली फ़िल्म 1913","हरिश्चंद्र: दादासाहेब फाल्के","हॉलीवुड का गहरा असर"],"निबंध को समझने के लिए सिनेमा का इतिहास जान लीजिए। चलचित्र की तकनीक पश्चिम में विकसित हुई और वहीं से भारत आई। उन्नीस सौ तेरह में दादासाहेब फाल्के ने भारत की पहली पूरी लंबाई की फ़िल्म, राजा हरिश्चंद्र, बनाई। इसके बाद भारत में फ़िल्में बनने लगीं और बहुत लोकप्रिय हुईं। पर शुरू से ही हॉलीवुड की शैली का गहरा असर रहा। राय का सवाल यही है कि जिस देश में इतनी समृद्ध कला परंपरा थी, वहाँ सिनेमा अपनी पहचान क्यों नहीं बना पाया।"),
C("🪞","नक़ल की समस्या",["हॉलीवुड के फ़ॉर्मूले उठाए गए","ऊपरी चमक-दमक अपनाई","गहराई और अपनी ज़िंदगी छूट गई","कला की भाषा को समझे बिना"],"पहली कमी जो राय बताते हैं, वह है नक़ल। भारतीय फ़िल्मकारों ने हॉलीवुड की फ़िल्मों से चमक-दमक, स्टाइल और फ़ॉर्मूले ले लिए, पर सिनेमा की कला को गहराई से नहीं समझा। इस कारण भारत की अपनी ज़िंदगी, अपनी सच्ची कहानियाँ और अपने पात्र पर्दे पर कम दिखे। नक़ल करने से हमें दूसरों जैसा दिखने का भ्रम तो मिलता है, पर अपनी पहचान नहीं बनती। यही बात पढ़ाई पर भी लागू होती है। अगर हम बिना समझे रटते हैं, तो ऊपरी ज्ञान तो मिलता है, पर गहराई नहीं।"),
C("🎭","बनावटीपन और अवास्तविकता",["बढ़ा-चढ़ाकर कहानियाँ","बेवजह गाने और नाच","बहुत लंबी फ़िल्में","दृश्य कहानी से जुड़े नहीं"],"दूसरी कमी है बनावटीपन। फ़िल्मों की कहानियाँ अवास्तविक और बढ़ा-चढ़ाकर दिखाई जाती थीं। जैसे हीरो अकेले बीस गुंडों को हरा दे, और अचानक गाँव से सीधे विदेश की बर्फ़ पर पहुँचकर गाना गाए। बेवजह गाने-नाच ठूँस दिए जाते और फ़िल्में बहुत लंबी हो जातीं। राय के अनुसार अच्छी फ़िल्म में एक साफ़ विषय, संतुलित ढाँचा और शुरू से अंत तक शैली की एकता होनी चाहिए। हर दृश्य को कहानी को आगे बढ़ाना चाहिए, सिर्फ़ समय भरने के लिए नहीं।"),
C("🎵","गाने: ज़रूरी या फ़ालतू",["संगीत भारत की आत्मा है","गाना कहानी से जुड़ा हो","भावना को गहरा करे","सिर्फ़ मनोरंजन के लिए ठूँसा न जाए"],"कई विद्यार्थी सोचते हैं कि राय गानों के बिल्कुल ख़िलाफ़ थे, पर ऐसा नहीं है। संगीत भारत की आत्मा है और हमारी फ़िल्मों की ख़ास पहचान भी। राय की आपत्ति गानों के बेवजह और अस्वाभाविक प्रयोग पर थी। गाना तब सुंदर लगता है जब वह कहानी का हिस्सा बने, भावना को गहरा करे और पात्र के मन को दिखाए। अगर गाना सिर्फ़ दर्शकों को लुभाने के लिए बीच में डाल दिया जाए, तो वह कहानी को कमज़ोर करता है। परीक्षा में यह अंतर स्पष्ट लिखिए।"),
C("🌾","ज़िंदगी कच्चा माल है",["अपने आसपास की ज़िंदगी देखिए","गाँव, खेत, नदी, गलियाँ","साधारण लोगों के सुख-दुख","सच्चाई और सादगी से दिखाइए"],"राय का समाधान बहुत साफ़ है। वे कहते हैं कि सिनेमा का कच्चा माल ज़िंदगी ख़ुद है। फ़िल्मकार को नक़ल छोड़कर अपने चारों ओर की ज़िंदगी देखनी चाहिए। भारत के गाँव, खेत, नदियाँ, शहर की गलियाँ, त्योहार और लोगों के सुख-दुख, यह सब कहानियों का अनंत भंडार है। बस उन्हें सच्चाई और सादगी से दिखाने की ज़रूरत है। यही सीख लेखन, कला और किसी भी काम में काम आती है। जब हम अपने अनुभव से लिखते हैं, तो हमारा काम असली और अलग दिखता है।"),
C("📽️","सिनेमा की अपनी भाषा",["चित्र, ध्वनि और गति की कला","कैमरा, रोशनी, संपादन","भाषण नहीं, दृश्य से कहानी","स्वाभाविक अभिनय"],"राय यह भी कहते हैं कि सिनेमा की अपनी एक भाषा है। यह नाटक या किताब से अलग कला है, जो चित्र, ध्वनि और गति से बनती है। इसलिए फ़िल्मकार को कैमरा, रोशनी, संपादन और अभिनय की गहरी समझ होनी चाहिए। अच्छी फ़िल्म में लंबे भाषणों की जगह दृश्यों के सहारे कहानी कही जाती है। अभिनय भी स्वाभाविक होना चाहिए, नाटकीय या बनावटी नहीं। एक चेहरे का भाव कई बार दस संवादों से ज़्यादा बोल जाता है। यही राय की फ़िल्मों की ख़ास पहचान थी।"),
C("🌧️","पथेर पांचाली की कहानी",["अपु और दुर्गा, दो बच्चे","गाँव की ग़रीबी","खेतों के पार पहली रेलगाड़ी","असली गाँव और नए कलाकार"],"राय ने सिर्फ़ लिखा नहीं, करके भी दिखाया। पथेर पांचाली उन्होंने असली गाँव में, ज़्यादातर नए कलाकारों के साथ और बहुत कम पैसों में बनाई। इसमें दो बच्चे हैं, अपु और उसकी बहन दुर्गा, जो ग़रीबी में भी छोटी-छोटी ख़ुशियाँ ढूँढ़ते हैं। एक प्रसिद्ध दृश्य है जिसमें दोनों खेतों के बीच पहली बार रेलगाड़ी देखते हैं। यह दृश्य बिना किसी बड़े संवाद के दर्शकों के मन में बस जाता है। यह फ़िल्म साबित करती है कि सच्ची और सादी कहानी भी महान सिनेमा बन सकती है।"),
C("📝","शब्दार्थ दोहराइए",["इमिटेट यानी नक़ल करना","रियलिज़्म यानी यथार्थ","थीम यानी विषय","कोहेरेंस यानी तालमेल"],"नए शब्द दोहराइए। इमिटेट यानी नक़ल करना, मीडियम यानी माध्यम, रियलिज़्म यानी यथार्थ, थीम यानी विषय, कोहेरेंस यानी तालमेल और रॉ मटेरियल यानी कच्चा माल। साथ में डायरेक्टर यानी निर्देशक, एक्टर यानी अभिनेता और स्टोरी यानी कहानी भी याद कर लीजिए। अब हर शब्द से अपना वाक्य बनाइए, जैसे गुड फ़िल्म्स शो रियलिज़्म, यानी अच्छी फ़िल्में यथार्थ दिखाती हैं। और डोंट इमिटेट अदर्स ब्लाइंडली, यानी दूसरों की आँख मूँदकर नक़ल मत करो।"),
C("🧩","व्याकरण: मोडल वर्ब",["शुड: सलाह","मस्ट: ज़रूरी","कैन: क्षमता","मे: संभावना"],"निबंध में सलाह और ज़रूरत वाले वाक्य बहुत हैं, इसलिए मोडल वर्ब याद कीजिए। शुड का मतलब है चाहिए, जैसे फ़िल्ममेकर्स शुड ऑब्ज़र्व लाइफ़, यानी फ़िल्मकारों को ज़िंदगी देखनी चाहिए। मस्ट यानी ज़रूर, जैसे ए फ़िल्म मस्ट हैव अ क्लियर थीम। कैन यानी सकता है, और मे यानी शायद। इन सबके बाद क्रिया का साधारण रूप आता है, टू नहीं लगता। अपनी पढ़ाई की आदतों पर चार वाक्य बनाइए जिनमें शुड, मस्ट, कैन और मे हों।"),
C("🎥","बिहार और सिनेमा",["तीसरी कसम: फणीश्वरनाथ रेणु की कहानी","भोजपुरी, मैथिली, मगही सिनेमा","लोक संस्कृति और गाँव की कहानियाँ","मोबाइल से भी अच्छी फ़िल्म संभव"],"बिहार का सिनेमा से भी गहरा नाता है। उन्नीस सौ छियासठ की प्रसिद्ध फ़िल्म तीसरी कसम बिहार के महान लेखक फणीश्वरनाथ रेणु की कहानी पर बनी, जो गाँव की सरल और सच्ची कथा है, और राय की सोच के बहुत क़रीब है। आज भोजपुरी, मैथिली और मगही में भी फ़िल्में बनती हैं। और अब तो मोबाइल कैमरे से भी अच्छी छोटी फ़िल्में बन सकती हैं। अगर आप अपने गाँव की किसी सच्ची कहानी पर तीन मिनट की फ़िल्म बनाएँ, तो वही राय की सलाह पर चलना होगा।"),
C("🧠","राय की सीख हर क्षेत्र के लिए",["नक़ल नहीं, मौलिकता","अपनी जड़ों से जुड़ें","ईमानदारी से काम करें","सादगी में शक्ति"],"यह निबंध सिर्फ़ फ़िल्मों पर नहीं, हर काम पर लागू होता है। चाहे आप पढ़ाई करें, खेती करें, कोई कारोबार करें या लिखें, नक़ल करने से आप सिर्फ़ दूसरों की छाया बनते हैं। पर जब आप अपनी जड़ों से जुड़कर ईमानदारी से काम करते हैं, तो आपका काम मौलिक और टिकाऊ होता है। सादगी में बड़ी शक्ति होती है। परीक्षा में अगर निबंध का संदेश पूछा जाए, तो लिखिए कि राय हमें नक़ल छोड़कर अपनी ज़िंदगी के प्रति सच्चा होने की सलाह देते हैं।"),
C("📌","निबंध का सार",["राय का सवाल: क्या कमी है","नक़ल और बनावटीपन मुख्य कमियाँ","समाधान: ज़िंदगी से कहानी लें","संदेश: सच्चाई और सादगी"],"अब निबंध का सार दोहरा लें। सत्यजित राय पूछते हैं कि भारतीय फ़िल्मों में क्या कमी है। उनके अनुसार मुख्य कमियाँ हैं हॉलीवुड की बिना समझे नक़ल, अवास्तविक और बनावटी कहानियाँ, और बेवजह के गाने-नाच। समाधान है कि फ़िल्मकार अपने आसपास की ज़िंदगी से कहानियाँ लें और उन्हें सच्चाई और सादगी से दिखाएँ। सिनेमा की अपनी भाषा समझना भी ज़रूरी है। इस सार को अपने शब्दों में पाँच वाक्यों में लिखकर अभ्यास कीजिए।"),
C("❓","संभावित परीक्षा प्रश्न",["लेखक कौन हैं","भारतीय फ़िल्मों की कमियाँ","राय का समाधान","पथेर पांचाली क्यों ख़ास"],"परीक्षा के प्रश्न देखिए। पहला, लेखक कौन हैं? उत्तर, सत्यजित राय, महान भारतीय फ़िल्मकार। दूसरा, भारतीय फ़िल्मों की कमियाँ क्या बताई गईं? उत्तर, पश्चिम की नक़ल, अवास्तविक कहानियाँ और बेवजह गाने-नाच। तीसरा, राय का समाधान? उत्तर, ज़िंदगी को कच्चा माल बनाना और सच्चाई तथा सादगी से फ़िल्म बनाना। चौथा, पथेर पांचाली क्यों ख़ास है? उत्तर, क्योंकि वह असली गाँव में सादगी और सच्चाई से बनी महान फ़िल्म है।"),
Q("क्या आपके अनुसार फ़िल्मों में गाने होने चाहिए? कारण सहित बताइए।","हाँ, पर वे कहानी से जुड़े और स्वाभाविक होने चाहिए, ज़बरदस्ती ठूँसे हुए नहीं।","एक सोचने वाला प्रश्न। क्या आपके अनुसार फ़िल्मों में गाने होने चाहिए? कारण सहित सोचिए। ... हाँ, पर वे कहानी से जुड़े और स्वाभाविक होने चाहिए, ज़बरदस्ती ठूँसे हुए नहीं। जब गाना भावना और कहानी को आगे बढ़ाता है, तभी वह अच्छा लगता है।"),
],7)
